from kit5 import *

WOODF = '#d9a868'
def skier(x, ground, s=1, col='#e2463b', rot=0):
    k = s
    g = pose((x, ground - 140 * k), (x - 4 * k, ground - 118 * k), (x - 10 * k, ground - 70 * k), arms=[[(x, ground - 114 * k), (x + 20 * k, ground - 90 * k), (x + 30 * k, ground - 78 * k)]], legs=[[(x - 10 * k, ground - 70 * k), (x + 10 * k, ground - 40 * k), (x, ground - 8 * k)]], back_arm=[[(x - 8 * k, ground - 114 * k), (x - 20 * k, ground - 90 * k), (x - 26 * k, ground - 80 * k)]], back_leg=[[(x - 12 * k, ground - 70 * k), (x + 2 * k, ground - 40 * k), (x - 12 * k, ground - 8 * k)]], shirt=col, pants='#2f3437', hr=15 * k, tw=30 * k, lw=13 * k, aw=10 * k)
    g += hat_('beret', x, ground - 140 * k, 15 * k, '#3c7fc1') + R(x - 14 * k, ground - 146 * k, 28 * k, 8 * k, '#f3c234', 3)
    g += R(x - 50 * k, ground - 4 * k, 100 * k, 5 * k, '#3c7fc1', 2) + L(x + 30 * k, ground - 78 * k, x + 40 * k, ground, '#5d6469', 2) + L(x - 26 * k, ground - 80 * k, x - 36 * k, ground, '#5d6469', 2)
    return G(g, f'rotate({rot} {x} {ground})')
def slope_bg():
    return R(0, 0, 200, 200, '#cfe2f0') + Pa('M0,60 L200,170 L200,200 L0,200 Z', '#ffffff') + Pa('M0,40 L50,10 L90,40 Z', '#ffffff', 'opacity=".7"') + ''.join(tree(170 - k * 30, 60 + k * 10, .3) for k in range(0))
def pine(x, base, s=1):
    return G(R(-4, -10, 8, 14, '#6a4a2a') + Pa('M0,-80 L24,-40 L12,-40 L30,-10 L-30,-10 L-12,-40 L-24,-40 Z', '#2f6a4a') + Pa('M0,-80 L10,-62 L-10,-62 Z', '#ffffff'), f'translate({x},{base}) scale({s})')
def skate_fig(x, ground, s=1, col='#7a4fa0'):
    k = s
    return pose((x, ground - 150 * k), (x, ground - 126 * k), (x, ground - 72 * k), arms=[[(x + 10 * k, ground - 122 * k), (x + 40 * k, ground - 120 * k), (x + 66 * k, ground - 130 * k)]], legs=[[(x, ground - 72 * k), (x - 2 * k, ground - 36 * k), (x, ground - 6 * k)]], back_arm=[[(x - 10 * k, ground - 122 * k), (x - 40 * k, ground - 120 * k), (x - 64 * k, ground - 114 * k)]], back_leg=[[(x, ground - 72 * k), (x - 34 * k, ground - 70 * k), (x - 70 * k, ground - 80 * k)]], shirt=col, pants=col, hr=15 * k, tw=28 * k, lw=12 * k, aw=9 * k, style='bun', hair='#3a2a20') + R(x - 14 * k, ground - 4 * k, 28 * k, 4 * k, '#c4cbd0', 2)
def ice_bg():
    return R(0, 0, 200, 200, '#cfe2f0') + R(0, 130, 200, 70, '#eef7fb') + St('M20,170 Q100,140 180,176', '#c4d8e4', 2) + St('M10,150 Q90,190 190,150', '#c4d8e4', 2)
def racecar(x, y, s=1, col='#e2463b', num='1'):
    return G(Pa('M-90,0 L-80,-20 L-30,-24 L-10,-40 L20,-40 L30,-24 L80,-20 L96,-6 L96,0 Z', col) + R(-96, -30, 14, 24, col, 2) + R(-100, -34, 22, 6, '#2f3437', 2) + R(84, -12, 18, 8, '#2f3437', 2) + Ci(6, -36, 10, '#3c7fc1') + Ci(6, -36, 10, '#ffffff', 'opacity=".2"') + Ci(-20, -12, 10, '#ffffff') + T(-20, -7, num, 13, '#2f3437', 900) + wheel(-60, 0, 16) + wheel(60, 0, 16), f'translate({x},{y}) scale({s})')
def race_road(y=150):
    return R(0, 0, 200, 200, SKY) + R(0, y - 10, 200, 10, '#8cc06a') + R(0, y, 200, 200 - y, ROAD) + ''.join(R(k * 20, y, 10, 6, ['#e2463b', '#ffffff'][k % 2]) for k in range(10))
def checkered(x, y, w, h, n=5, m=4):
    return ''.join(R(x + i * w / n, y + j * h / m, w / n, h / m, '#2f3437' if (i + j) % 2 else '#ffffff') for i in range(n) for j in range(m))
def gym_bg():
    return R(0, 0, 200, 200, '#e6e2dc') + R(0, 150, 200, 50, '#5d6469') + R(0, 20, 200, 8, '#c4cbd0', 0, 'opacity=".5"')
def dumbbell(x, y, s=1, rot=0, col='#2f3437'):
    return G(R(-30, -4, 60, 8, '#a7adb1', 2) + R(-40, -16, 12, 32, col, 3) + R(-50, -12, 10, 24, col, 3) + R(28, -16, 12, 32, col, 3) + R(40, -12, 10, 24, col, 3), f'translate({x},{y}) rotate({rot}) scale({s})')
def treadmill(x, base, s=1):
    return G(Pa('M-70,0 L70,0 L80,-14 L-60,-14 Z', '#2f3437') + R(-60, -18, 140, 6, '#5d6469', 3) + L(60, -14, 70, -90, '#8a9196', 6) + R(50, -104, 40, 22, '#3a4048', 4) + R(56, -100, 28, 12, '#7cc05a', 2), f'translate({x},{base}) scale({s})')
def ebike(x, base, s=1):
    return G(R(-40, -10, 80, 10, '#2f3437', 4) + L(-20, -10, -14, -60, '#8a9196', 6) + R(-28, -66, 30, 8, '#2f3437', 4) + L(30, -10, 36, -80, '#8a9196', 6) + R(28, -92, 30, 16, '#3a4048', 4) + Ci(20, -30, 16, '#5d6469') + Ci(20, -30, 6, '#a7adb1'), f'translate({x},{base}) scale({s})')
def yoga_mat(x, y, w, col='#7fc4c0'):
    return R(x, y, w, 10, col, 4) + E(x + w, y + 5, 8, 10, shade(col, -.15))
def pins(x, base, s=1):
    return G(''.join(G(Pa('M0,-50 Q10,-50 8,-36 Q6,-30 8,-24 Q14,-10 10,0 L-10,0 Q-14,-10 -8,-24 Q-6,-30 -8,-36 Q-10,-50 0,-50 Z', '#ffffff', 'stroke="#c4cbd0" stroke-width="1.5"') + R(-7, -34, 14, 3, '#e2463b') + R(-7, -29, 14, 3, '#e2463b'), f'translate({dx},{dy})') for dx, dy in [(0, -16), (-14, -8), (14, -8), (-28, 0), (0, 0), (28, 0)]), f'translate({x},{base}) scale({s})')
def dartboard(x, y, r):
    g = ''
    for k, c in enumerate(['#2f3437', '#f6efe0', '#e2463b', '#f6efe0', '#5ba644', '#e2463b']):
        g += Ci(x, y, r * (1 - k * .16), c)
    return g + ''.join(L(x, y, x + r * math.cos(a), y + r * math.sin(a), '#c4cbd0', 1) for a in [k * math.pi / 10 for k in range(20)])
def target_arch(x, y, r):
    return ''.join(Ci(x, y, r * (1 - k * .2), c) for k, c in enumerate(['#ffffff', '#2f3437', '#3c7fc1', '#e2463b', '#f3c234']))
def skateboard(x, y, s=1, rot=0):
    return G(R(-60, -6, 120, 12, '#e2463b', 6) + Ci(-40, 12, 8, '#f3c234') + Ci(40, 12, 8, '#f3c234') + R(-44, 4, 8, 6, '#a7adb1') + R(36, 4, 8, 6, '#a7adb1'), f'translate({x},{y}) rotate({rot}) scale({s})')

